cd /testbed && source /opt/miniconda3/bin/activate testbed && python -c "
from exceptiongroup import ExceptionGroup

# Test 1: Basic ExceptionGroup creation
try:
    raise ExceptionGroup('test', [ValueError('v1'), TypeError('t1')])
except ExceptionGroup as eg:
    print('Test 1 - Basic EG creation: PASSED')
    print(f'  Message: {eg.message}')
    print(f'  Exceptions: {eg.exceptions}')
    print(f'  Has __traceback__: {eg.__traceback__ is not None}')
    print(f'  Has __cause__: {eg.__cause__ is not None}')
    print(f'  Has __context__: {eg.__context__ is not None}')

# Test 2: Nested ExceptionGroups
try:
    raise ExceptionGroup('outer', [
        ExceptionGroup('inner', [ValueError('v1')]),
        TypeError('t1')
    ])
except ExceptionGroup as eg:
    print('Test 2 - Nested EG: PASSED')
    print(f'  Outer message: {eg.message}')
    print(f'  Outer __traceback__: {eg.__traceback__ is not None}')
    for sub in eg.exceptions:
        if isinstance(sub, ExceptionGroup):
            print(f'  Inner message: {sub.message}')
            print(f'  Inner __traceback__: {sub.__traceback__ is not None}')

# Test 3: ExceptionGroup with cause
try:
    try:
        raise ValueError('original')
    except ValueError as e:
        raise ExceptionGroup('group', [TypeError('t1')]) from e
except ExceptionGroup as eg:
    print('Test 3 - EG with cause: PASSED')
    print(f'  Has __cause__: {eg.__cause__ is not None}')
    if eg.__cause__:
        print(f'  Cause type: {type(eg.__cause__).__name__}')

print('\\nAll tests PASSED!')
"

